# Charmer ★1: young apprentice, pointed cap with stars, a little wand
add('pt96','#5a6ab8','#20285a','#f2c9a6','#6b3f26',6,body('#3a4a9a'),smile+'<path d="M84 104 L140 0 L196 104Z" fill="#2a3a8a"/><ellipse cx="140" cy="104" rx="64" ry="12" fill="#1a2a6a"/>'+star(124,60,'#e8c070')+star(156,34,'#e8c070')+'<g transform="translate(214 230) rotate(-30)"><rect x="-3" y="-50" width="6" height="64" fill="#3a2214"/>'+star(0,-56,'#ffe08a')+'</g>')
