add('pt99','#3a8a8a','#123a3a','#d9a27a','#1d1410',7,body('#3a3a3a')+'<path d="M96 214 Q140 230 184 214 L188 280 H92Z" fill="#7a6a5a"/>',smile+'<path d="M84 108 Q84 56 140 52 Q196 56 196 108Z" fill="#c9c3bb"/><rect x="84" y="84" width="112" height="12" fill="#3a3a3a"/><circle cx="116" cy="90" r="15" fill="#9fe0d6" stroke="#3a3a3a" stroke-width="5"/><circle cx="164" cy="90" r="15" fill="#9fe0d6" stroke="#3a3a3a" stroke-width="5"/><g transform="translate(214 230)"><path d="M-8 -34 H8 V-12 L24 22 Q26 32 14 32 H-14 Q-26 32 -24 22 L-8 -12Z" fill="#e8f4ff" opacity=".85"/><path d="M-20 14 Q0 6 20 14 L24 22 Q26 32 14 32 H-14 Q-26 32 -24 22Z" fill="#9be37a"/><circle cx="-4" cy="2" r="4" fill="#9be37a"/><circle cx="6" cy="-10" r="3" fill="#9be37a"/><circle cx="0" cy="-26" r="2.5" fill="#9be37a"/></g>')
